{
  "candidate_id": "phase3-acceptance-mg-iii-rules-batch-1",
  "created_by_agent_call_id": "agent-call-001",
  "proposed_rules": [
    {
      "official_code": "IN-01",
      "components": [
        {
          "title": "年龄18~75周岁（包括边界值）",
          "expression": {
            "kind": "logical",
            "operator": "all",
            "children": [
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-01-age-min",
                  "subject": "受试者年龄",
                  "attribute": "年龄",
                  "comparator": "gte",
                  "value": 18,
                  "unit": "周岁",
                  "source_term": "年龄",
                  "source_clause": "年龄18~75周岁（包括边界值）",
                  "requires_professional_judgment": false
                },
                "time_constraint": null
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-01-age-max",
                  "subject": "受试者年龄",
                  "attribute": "年龄",
                  "comparator": "lte",
                  "value": 75,
                  "unit": "周岁",
                  "source_term": "年龄",
                  "source_clause": "年龄18~75周岁（包括边界值）",
                  "requires_professional_judgment": false
                },
                "time_constraint": null
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "demographics",
              "due_stage": "screening",
              "description": "受试者年龄记录（人口学资料）",
              "required_source_types": ["demographic_record"],
              "allows_screening_record_transcription": true,
              "requires_contemporaneous_objective_source": false
            }
          ],
          "source_span_ids": [
            "phase3-acceptance-mg-iii-snapshot::body.p548"
          ],
          "source_excerpts": [
            "年龄18~75周岁（包括边界值），男女不限；"
          ]
        }
      ]
    },
    {
      "official_code": "IN-02",
      "components": [
        {
          "title": "符合SAR诊断且病史≥2年且sIgE符合标准",
          "expression": {
            "kind": "logical",
            "operator": "all",
            "children": [
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-02-diagnosis",
                  "subject": "受试者",
                  "attribute": "符合季节性过敏性鼻炎的诊断（参照指南）",
                  "comparator": "eq",
                  "value": true,
                  "source_clause": "参照《中国变应性鼻炎诊断和治疗指南（2022年，修订版）》受试者符合季节性过敏性鼻炎的诊断",
                  "requires_professional_judgment": true
                },
                "time_constraint": null
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-02-history-duration",
                  "subject": "既往病史",
                  "attribute": "持续时间",
                  "comparator": "gte",
                  "value": 2,
                  "unit": "年",
                  "source_term": "既往明确病史",
                  "source_clause": "既往明确病史≥2年",
                  "requires_professional_judgment": false
                },
                "time_constraint": null
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-02-sige",
                  "subject": "sIgE检测结果",
                  "attribute": "存在至少一种与当前季节或同期过敏性鼻炎发病相关且符合指南对SAR的诊断标准",
                  "comparator": "eq",
                  "value": true,
                  "source_clause": "筛选/导入期至少一种与当前季节或同期过敏性鼻炎发病相关的sIgE检测结果符合指南对SAR的诊断标准",
                  "requires_professional_judgment": true
                },
                "time_constraint": null
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "medical_history",
              "due_stage": "screening",
              "description": "SAR及哮喘病史和治疗史，用于确认SAR诊断及病史持续时间",
              "required_source_types": ["medical_history_record"],
              "allows_screening_record_transcription": true,
              "requires_contemporaneous_objective_source": false
            },
            {
              "fact_type": "allergen_lab_test",
              "due_stage": "screening",
              "description": "过敏原筛查（sIgE检测）结果",
              "required_source_types": ["lab_result"],
              "allows_screening_record_transcription": true,
              "requires_contemporaneous_objective_source": false
            }
          ],
          "source_span_ids": [
            "phase3-acceptance-mg-iii-snapshot::body.p549"
          ],
          "source_excerpts": [
            "参照《中国变应性鼻炎诊断和治疗指南（2022年，修订版）》受试者符合季节性过敏性鼻炎的诊断，既往明确病史≥2年，筛选/导入期至少一种与当前季节或同期过敏性鼻炎发病相关的sIgE检测结果符合指南对SAR的诊断标准；"
          ]
        }
      ]
    },
    {
      "official_code": "IN-03",
      "components": [
        {
          "title": "当前或既往同期花粉季节使用SAR药物且症状控制不佳",
          "expression": {
            "kind": "logical",
            "operator": "all",
            "children": [
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-03-season",
                  "subject": "受试者",
                  "attribute": "当前或既往同期花粉季节",
                  "comparator": "eq",
                  "value": true,
                  "source_clause": "受试者在当前或既往同期花粉季节",
                  "requires_professional_judgment": true
                },
                "time_constraint": null
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-03-drug-type",
                  "subject": "受试者",
                  "attribute": "使用治疗SAR药物类型",
                  "comparator": "in",
                  "value": ["鼻喷糖皮质激素", "其他治疗SAR药物"],
                  "source_term": "治疗SAR药物",
                  "source_clause": "使用鼻喷糖皮质激素或其他治疗SAR药物",
                  "requires_professional_judgment": false
                },
                "time_constraint": null
              },
              {
                "kind": "predicate",
                "predicate": {
                  "predicate_id": "IN-03-poor-control",
                  "subject": "受试者",
                  "attribute": "SAR症状控制不佳",
                  "comparator": "eq",
                  "value": true,
                  "source_clause": "SAR症状控制不佳",
                  "requires_professional_judgment": true
                },
                "time_constraint": null
              }
            ]
          },
          "evidence_requirements": [
            {
              "fact_type": "treatment_history",
              "due_stage": "screening",
              "description": "受试者当前或既往花粉季节使用治疗SAR药物的用药史记录",
              "required_source_types": ["medical_history_record"],
              "allows_screening_record_transcription": true,
              "requires_contemporaneous_objective_source": false
            },
            {
              "fact_type": "clinical_response_assessment",
              "due_stage": "screening",
              "description": "研究者对SAR症状控制情况的评估记录",
              "required_source_types": ["clinical_assessment_record"],
              "allows_screening_record_transcription": true,
              "requires_contemporaneous_objective_source": false
            }
          ],
          "source_span_ids": [
            "phase3-acceptance-mg-iii-snapshot::body.p550"
          ],
          "source_excerpts": [
            "受试者在当前或既往同期花粉季节，使用鼻喷糖皮质激素或其他治疗SAR药物（抗组胺药、白三烯受体拮抗剂等），SAR症状控制不佳；"
          ]
        }
      ]
    }
  ]
}

