              },
              {
                "kind": "logical",
                "operator": "any",
                "children": [
                  {
                    "kind": "predicate",
                    "predicate": {
                      "predicate_id": "IN-04-baseline-rhinorrhea",
                      "subject": "受试者",
                      "attribute": "基线时流鼻涕评分",
                      "comparator": "gte",
                      "value": 2,
                      "unit": "分",
                      "source_term": null,
                      "source_clauses": [
                        "基线时",
                        "流鼻涕、鼻痒和打喷嚏三种症状之一≥2分"
                      ],
                      "requires_professional_judgment": false
                    },
                    "time_constraint": null
                  },
                  {
                    "kind": "predicate",
                    "predicate": {
                      "predicate_id": "IN-04-baseline-nasal-itch",
                      "subject": "受试者",
                      "attribute": "基线时鼻痒评分",
                      "comparator": "gte",
                      "value": 2,
                      "unit": "分",
                      "source_term": null,
                      "source_clauses": [
                        "基线时",
                        "流鼻涕、鼻痒和打喷嚏三种症状之一≥2分"
                      ],
                      "requires_professional_judgment": false
                    },
                    "time_constraint": null
                  },
                  {
                    "kind": "predicate",
                    "predicate": {
                      "predicate_id": "IN-04-baseline-sneeze",
                      "subject": "受试者",
                      "attribute": "基线时打喷嚏评分",
                      "comparator": "gte",
                      "value": 2,
                      "unit": "分",
                      "source_term": null,
                      "source_clauses": [
                        "基线时",
                        "流鼻涕、鼻痒和打喷嚏三种症状之一≥2分"
                      ],
