            "kind": "predicate",
            "predicate": {
              "predicate_id": "IN-06-wocbp-contraception",
              "subject": "有生育能力的女性受试者及其伴侣",
              "attribute": "同意采取高效的避孕措施",
              "comparator": "eq",
              "value": true,
              "source_term": null,
              "source_clauses": [
                "整个研究期间（从签署ICF到研究药物给药后6个月）",
