            "time_constraint": null
          },
          "evidence_requirements": [
            {
              "fact_type": "contraception_agreement",
              "due_stage": "screening",
              "description": "记录男性受试者及其伴侣同意在整个研究期间（从签署ICF到研究药物给药后6个月）采取有效避孕措施",
              "required_source_types": ["informed_consent_form", "clinical_assessment_record"],
              "allows_screening_record_transcription": true,
              "requires_contemporaneous_objective_source": false
            }
          ],
          "source_span_ids": [
            "phase3-acceptance-mg-iii-snapshot::body.p556"
          ],
          "source_excerpts": [
            "整个研究期间（从签署ICF到研究药物给药后6个月），有生育能力的女性受试者及其伴侣同意采取高效的避孕措施，男性受试者及其伴侣同意采取有效的避孕措施且无捐献精子（男性）或卵子（女性）的计划；"
          ]
        },
        {
          "title": "无捐献精子（男性）或卵子（女性）的计划",
          "expression": {
